window.__SIM_TOPICS={"scraps-design": {"key": "scrap-design", "summary": "Capture first, keep the originals, one tap for the common action: the ideas the design notes and the whiteboard keep returning to.", "text": "## Overview\n\nscrap is built around capture: the phone saves first and uploads later, and every original is kept.\n\n## Key facts\n\n- One process, no login, in v0 ([[2026-10-21-13-52]]).\n- The common action is one tap ([[scrap-design-notes]]).\n\n## Open questions\n\n- How long titles should wrap in a list.", "sources": ["scrap-design-notes", "2026-10-21-13-52", "body-text-for-the-long-title-check"]}, "search-and-storage": {"key": "scrap-search", "summary": "SQLite holds everything; sqlite-vec may add similar-page search, and the page cap keeps big pages in check.", "text": "## Overview\n\nEverything lives in SQLite. Two open threads: vector search with sqlite-vec, and the page size cap.\n\n## Key facts\n\n- The cap is under review in PR 125.", "sources": ["look-at-sqlite-vec-0-2-release-notes", "review-pr-125-page-cap", "scrap-design-notes"]}, "the-garden-through-the-year": {"key": "garden", "summary": "Bulbs before the first frost, a fence panel to mend, and the front border at its best in late summer.", "text": "## Overview\n\nThe garden's year in three notes: planting, repairs and what flowered.", "sources": ["front-border-in-flower", "fix-the-broken-fence-panel", "plant-the-tulip-bulbs-before-the-first-frost-move-the-rosema"]}, "running-the-house": {"key": "house", "summary": "Gutters, the boiler, the gas safety certificate for the tenant and the dog's food: the jobs that come round again.", "text": "## Overview\n\nThe house's recurring jobs, and who to call for each.", "sources": ["clear-the-gutters", "call-the-plumber-about-the-boiler", "send-the-gas-safety-certificate-to-the-tenants", "buy-dog-food"]}, "keeping-the-car-on-the-road": {"key": "car", "summary": "The MOT and the insurance renewal fall in the same month.", "text": "## Overview\n\nTwo dates a year: the MOT and the insurance.", "sources": ["book-the-mot", "renew-car-insurance"]}, "ioc-upkeep": {"key": "ioc-upkeep", "summary": "Releasing ibek 4.1, a spare power supply for the IOCs, and what the weekly controls sync decided.", "text": "## Overview\n\nThe controls work that keeps coming back: releases, spares and the weekly sync.", "sources": ["release-ibek-4-1", "order-a-spare-ioc-power-supply", "weekly-controls-sync"]}, "minds-and-machines": {"key": "minds", "summary": "Blindsight, integrated information theory and Anthropic's research: what it would take for a machine to be aware.", "text": "## Overview\n\nThree reads that circle the same question.", "sources": ["blindsight-by-peter-watts-recommended-after-permutation-city", "https-www-anthropic-com-research", "https-en-wikipedia-org-wiki-integrated-information-theory"]}, "who-to-ask": {"key": "who-to-ask", "summary": "The contacts index: where to find family, colleagues and the people who fix things.", "text": "## Overview\n\nOne index page links the people searches.", "sources": ["contacts"]}};
